import type {RecordRow as R} from './erp-engine';
export const companyProfiles:Record<string,{industry:string;stages:string[];services:string[];sectors:string[];billing:string[];costs:string[];feeBases:string[];crmFields:[string,string][]}>={
Hagadol:{industry:'Water infrastructure and solutions',stages:['New','Qualified','Site assessment','Technical design','Quotation','Negotiation','Pending deposit','Won','Lost'],services:['Boreholes','Water supply','Solar pumping','Water treatment','Irrigation','Maintenance'],sectors:['School','Clinic','NGO / community','Home','Farm','Factory','Government'],billing:['Deposit','Materials supply','Installation','Commissioning','Handover','Maintenance'],costs:['Survey and siting','Drilling and casing','Pumps and solar','Treatment equipment','Pipes and storage','Field labour','Transport and mobilisation','Maintenance','Administration'],feeBases:['Fixed quotation','Measured BOQ','Equipment supply','Service visit'],crmFields:[['Site location','siteLocation'],['Water need and daily demand','waterNeed'],['Existing source and evidence','sourceEvidence']]},
WMK:{industry:'Architecture and design',stages:['New','Qualified','Design brief','Fee proposal','Negotiation','Won','Lost'],services:['Architecture','Interior design','Site supervision','Construction management','Planning consultancy'],sectors:['Residential','Commercial','Institutional','Developer','NGO','Government'],billing:['Appointment deposit','Concept design','Design development','Construction drawings','Approvals','Site supervision','Final account'],costs:['Design consultants','Survey and site information','Drawings and printing','Approval submissions','Site supervision','Travel and site visits','Professional services','Administration'],feeBases:['Fixed professional fee','Percentage of works value','Stage fee','Time based fee','Monthly supervision'],crmFields:[['Site / plot reference','plotReference'],['Building use and client brief','designBrief'],['Appointment and approval requirements','appointmentRequirements']]}
};
export function profile(company:string){return companyProfiles[company]||companyProfiles.Hagadol;}
export function dealStages(company:string){return company==='Group'?[...new Set(Object.values(companyProfiles).flatMap(p=>p.stages))]:profile(company).stages;}
export function displayDealStage(company:string,status:string){return company==='WMK'&&status==='Quotation'?'Fee proposal':status;}
export function validateIndustryRecord(r:R){
const p=profile(r.company);for(const [k,options] of [['businessLine',p.services],['clientSector',p.sectors],['billingStage',p.billing],['costCategory',p.costs],['feeBasis',p.feeBases]] as [string,string[]][]){if(r[k]&&!options.includes(r[k]))throw Error('Choose a '+k.replace(/[A-Z]/g,c=>' '+c.toLowerCase())+' for '+r.company+'.');r[k]=String(r[k]||'').trim();}
for(const [,key] of p.crmFields)r[key]=String(r[key]||'').trim().slice(0,5000);
if(['deal','contact'].includes(r.type))for(const [,key] of Object.values(companyProfiles).filter(x=>x!==p).flatMap(x=>x.crmFields))delete r[key];
return r;
}
